 (new App\Application\Academic\Commands\ReplaceTeacher($db))->execute($director,$assignment,['teacher_id'=>$foreignTeacher->identityId]);$denied('forbidden',fn()=>$service->assess($foreignTeacher,$first['id'],array_replace($input,['expected_assessment_id'=>$corrected['assessment_id']])));
