 (new App\Application\Academic\Commands\TransferStudent($db))->execute($director,$enrollment,['grade_id'=>$grade,'section_id'=>$other]);$assert(count($service->history($student,$first['id'],null)['items'])===4);
 foreach([fn()=>$db->table('delivery_assessments')->where('id',$initial['assessment_id'])->update(['grade'=>'C']),fn()=>$db->table('delivery_assessments')->where('id',$initial['assessment_id'])->delete()] as $mutation){try{$mutation();throw new RuntimeException('Assessment unexpectedly changed');}catch(Illuminate\Database\QueryException){$assert(true);}}
