 $fixtureAssignment=$assignments->create($director,['teacher_id'=>$teacher->identityId,'academic_period_id'=>$fixturePeriod,'instructional_entry_id'=>$entry,'grade_id'=>$grade,'section_id'=>$section,'effective_from'=>$today,'effective_until'=>'2026-12-31']);
 $fixture=(new App\Infrastructure\Persistence\Academic\AcademicWriteTransaction($db))->execute($director->identityId,
  fn()=>new App\Infrastructure\Persistence\Academic\AcademicLockSet(['academic_periods'=>[$fixturePeriod],'retained_identities'=>[$teacher->identityId,$student->identityId],'teaching_assignments'=>[$fixtureAssignment]]),
  fn()=>true,
  function($context,$boundary)use($db,$teacher,$student,$fixturePeriod,$fixtureAssignment,$grade,$section,$today){
   $key=$boundary->toServerKey();$stamp=$boundary->timestamp->format('Y-m-d H:i:s.u');
   $db->table('academic_periods')->where('id',$fixturePeriod)->update(['state'=>'closed']);
